function fmtScore(value: number | null) { return value === null ? "—" : value.toFixed(1); }
function countBy<T>(items: T[], key: (item: T) => string) { return items.reduce<Record<string,number>>((all,item) => { const k=key(item); all[k]=(all[k]||0)+1; return all; },{}); }
function vendorLocation(locations:Item[],vendorId:string){const rows=locations.filter(location=>location.vendor_id===vendorId);return rows.find(location=>location.is_primary)||rows.find(location=>location.location_type==="headquarters")||rows[0];}
function vendorHasLocation(locations:Item[],vendorId:string,country:string,state:string){const rows=locations.filter(location=>location.vendor_id===vendorId);return (!country||rows.some(location=>location.iso_country_code===country))&&(!state||rows.some(location=>location.iso_country_code==="USA"&&(state==="Unknown"?!location.us_state_code:location.us_state_code===state)));}
function robotsForDistributor(data:Data,distributorId:string){return linkedRobots(data.robots,data.distributorLinks,distributorId);}
function distributorOutreachForMeetup(data:Data,distributorId:string,meetupId:string){return currentDistributorOutreach(data.distributorOutreach,distributorId,meetupId);}
function Score({ value, provisional }: { value: number | null; provisional?: boolean }) { return <span className={"score" + (value===null?" empty":"")}>{fmtScore(value)} {provisional && <span className="badge warn">Provisional</span>}</span>; }

