  async function saveLocation(record:Record<string,unknown>){
    if(!db||!canEdit)throw new Error("You do not have permission to edit locations.");
    const values={...record,vendor_id:id};
    const {id:locationId,...fields}=values as Record<string,unknown>;
    const query=typeof locationId==="string"?db.from("vendor_locations").update(fields as never).eq("id",locationId).eq("vendor_id",id).eq("workspace_id",workspaceId):db.from("vendor_locations").insert({...fields,workspace_id:workspaceId} as never);
    const {error}=await query.select("id").single();
    if(error)throw new Error(error.message);
    await load();setNotice("Location saved");
  }
  async function deleteLocation(locationId:string){
    if(!db||!canEdit)throw new Error("You do not have permission to delete locations.");
    const {data:deleted,error}=await db.from("vendor_locations").delete().eq("id",locationId).eq("vendor_id",id).eq("workspace_id",workspaceId).select("id").single();
    if(error)throw new Error(error.message);
    if(!deleted)throw new Error("Location was not deleted. Refresh and try again.");
    await load();setNotice("Location deleted");
  }
