function RobotCreateForm({vendors,defaultVendorId,onCancel,onCreated}:{vendors:Item[];defaultVendorId?:string;onCancel:()=>void;onCreated:(id:string)=>Promise<void>}){
  const [vendorId,setVendorId]=useState(defaultVendorId||vendors[0]?.id||""),[name,setName]=useState(""),[productUrl,setProductUrl]=useState(""),[description,setDescription]=useState(""),[busy,setBusy]=useState(false),[error,setError]=useState("");
  async function submit(){if(busy)return;setError("");if(!vendorId){setError("Add a vendor first, then choose it here.");return;}if(!name.trim()){setError("Enter a robot name.");return;}setBusy(true);try{const {count,error:countError}=await db!.from("robots").select("id",{count:"exact",head:true}).eq("vendor_id",vendorId);if(countError)throw countError;const {data,error}=await db!.from("robots").insert({workspace_id:workspaceId,vendor_id:vendorId,name:name.trim(),normalized_name:normalizeName(name),product_url:productUrl.trim()||null,description:description.trim()||null,is_flagship:count===0,research_status:"queued"}).select("id").single();if(error)throw error;await onCreated(data.id);}catch(cause){setError(cause instanceof Error?cause.message:"Could not add robot");}finally{setBusy(false);}}
  return <section className="card stack" aria-labelledby="add-robot-title"><h2 id="add-robot-title">Add robot</h2><p className="muted">{defaultVendorId?"Add a robot model for "+(vendors.find(v=>v.id===defaultVendorId)?.name||"this vendor")+".":"Choose its vendor and enter a model name."} Research and scores can be added from its profile.</p><div className="form-grid">{!defaultVendorId&&<label className="field">Vendor<select className="select" value={vendorId} onChange={e=>setVendorId(e.target.value)}><option value="">Choose a vendor</option>{vendors.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(v=><option key={v.id} value={v.id}>{v.name}</option>)}</select></label>}<label className="field">Robot name<input className="input" required value={name} onChange={e=>setName(e.target.value)}/></label><label className="field">Product URL<input className="input" type="url" value={productUrl} onChange={e=>setProductUrl(e.target.value)}/></label><label className="field">Description<input className="input" value={description} onChange={e=>setDescription(e.target.value)}/></label></div>{error&&<p className="notice error" role="alert">{error}</p>}<div className="toolbar"><button className="button primary" disabled={busy} onClick={submit}>{busy?"Saving…":"Save robot"}</button><button className="button" disabled={busy} onClick={onCancel}>Cancel</button></div></section>;
}
